const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;

const ambient = new THREE.AmbientLight(0x7f8aa6, 0.32);
const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
keyLight.position.set(5, 8, 6);
const pointLight = new THREE.PointLight(0xaaddff, 1.0, 18);
pointLight.position.set(-4, 2, -4);
scene.add(ambient, keyLight, pointLight);

const heroGroup = new THREE.Group();
scene.add(heroGroup);

const geometry = new THREE.BoxGeometry(1.6, 1.6, 1.6);
const material = new THREE.MeshStandardMaterial({ color: 0xd93025, roughness: 0.35, metalness: 0.1 });
const cube = new THREE.Mesh(geometry, material);
cube.castShadow = true;
cube.receiveShadow = true;
heroGroup.add(cube);

camera.position.set(3.2, 2.2, 4.2);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  heroGroup.rotation.y = t * 0.6;
  heroGroup.rotation.x = Math.sin(t * 0.4) * 0.08;
  controls.update();
  renderer.render(scene, camera);
}
animate();

